using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Collections.Generic;
using System.Diagnostics;
using System.Threading;
namespace UnturnedModManager {
 public static class WorkflowTests {
  static List<string> lines;static void Check(bool ok,string text){if(!ok)throw new Exception("FAIL "+text);lines.Add("PASS "+text);Console.WriteLine(lines.Last());}
  static void Reject(Action action,string text){bool rejected=false;try{action();}catch{rejected=true;}Check(rejected,text);}
  static Package Native(string root,string id,string version,string payload="data"){string source="payload/Modules/Test/"+id+".dll";string file=Paths.Safe(root,source);Directory.CreateDirectory(Path.GetDirectoryName(file));File.WriteAllText(file,payload);Data.Write(Path.Combine(root,Packages.ManifestName),new PackageManifest{schemaVersion=1,id=id,name="Same name",version=version,kind="module",files=new List<PackageFile>{new PackageFile{source=source,target="Modules/Test/"+id+".dll",sha256=Data.Hash(file)}}});return Packages.Load(root,L.Get("Text227"));}
  static string NewRoot(string baseDir,string prefix){string root=Path.Combine(Path.GetFullPath(baseDir),prefix+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);return root;}
  static string FakeGame(string root){string game=Path.Combine(root,"Library","steamapps","common","Unturned");Directory.CreateDirectory(game);File.WriteAllText(Path.Combine(game,"Unturned.exe"),"fixture executable");return game;}
  public static int Run(string baseDir){lines=new List<string>();string root=NewRoot(baseDir,"workflow-"),game=FakeGame(root),sources=Path.Combine(root,"sources"),state=Path.Combine(root,"state");
   Check(VersionOrder.Compare("1.0.10","1.0.9")>0&&VersionOrder.Compare("1.0.7-test1","1.0.7")<0,"numeric and prerelease versions compare predictably");Check(VersionOrder.Compare("2026.10.29.1","2026.10.28.9")>0&&VersionOrder.Compare("beta-2","1.0.0")==null,"date versions compare and unknown formats remain explicitly incomparable");
   Reject(()=>Paths.CheckTarget("Modules/Other/x.dll","module","12345"),"scoped policy cannot be promoted to executable-module writes");
   Check(WorkshopTargets.ContentRoots(game+Path.DirectorySeparatorChar,new string[0]).Single()==Path.Combine(root,"Library","steamapps","workshop","content","304930"),"target paths with a trailing separator retain the correct Steam library");
   var test=Native(Path.Combine(root,"beta"),"test.beta","beta-2");var old=Native(Path.Combine(root,"old"),"test.beta","1.0.0");var e=new Engine(game,state,true);e.Install(test,null);Reject(()=>e.Install(old,null),"incomparable installed version requires explicit switch confirmation");e.Install(old,null,true);e.Uninstall(old.Manifest.id);
   var uncertain=PackageVersions.Options(new[]{test,old});Check(uncertain.Count==2&&!uncertain.Any(o=>o.Label.Contains(L.Get("Text230"))),"unknown version set has no invented latest recommendation");
   var sameA=Native(Path.Combine(root,"copy-a"),"test.same","1.0.0","A");var sameB=Native(Path.Combine(root,"copy-b"),"test.same","1.0.0","B");Check(PackageVersions.Options(new[]{sameA,sameB,sameA}).Count==2,"same-version distinct source copies are preserved and identical paths deduplicated");
   var difference=VersionDifference.Compare(sameA,sameB);Check(difference.Changed.Count==1&&difference.Added.Count==0&&difference.Removed.Count==0,"version comparison detects different payload hashes without merging source copies");
   Directory.CreateDirectory(sources);for(int mod=0;mod<120;mod++)for(int version=0;version<6;version++)Native(Path.Combine(sources,mod.ToString("D3"),version.ToString()),"stress.mod"+mod,"1.0."+version);
   var timer=Stopwatch.StartNew();var cold=Scanner.Collect(root,state,game,sources,new[]{Path.Combine(sources,"000","0")},new string[0],false,delegate{});long coldMs=timer.ElapsedMilliseconds;timer.Restart();var warm=Scanner.Collect(root,state,game,sources,new[]{Path.Combine(sources,"000","0")},new string[0],false,delegate{});long warmMs=timer.ElapsedMilliseconds;
   Check(cold.Available.Count==720&&cold.Available.GroupBy(p=>p.Manifest.id).Count()==120,"720 versions and 120 IDs retain separate identities despite identical names");Check(warm.Available.Count==720&&warm.ParsedPackages==0&&warm.CacheHits==720,"warm scan reuses all metadata and duplicate remembered root is visited once");
   string changed=Path.Combine(sources,"000","0",Packages.ManifestName);var manifest=Data.Read<PackageManifest>(changed);manifest.name="Changed name";Data.Write(changed,manifest);var revised=Scanner.Collect(root,state,game,sources,new string[0],new string[0],false,delegate{});Check(revised.ParsedPackages==1&&revised.Available.Any(p=>p.Manifest.name=="Changed name"),"changed manifest invalidates one cached package");
   var cancellation=new CancellationTokenSource();cancellation.Cancel();Reject(()=>Scanner.Collect(root,state,game,sources,new string[0],new string[0],false,delegate{},false,cancellation.Token),"scan cancellation propagates before changing installed files");Check(ScanCache.Count<=4096&&ScanCache.FileCount<=100000,"scan cache is bounded");
   var imported=Native(Path.Combine(state,"imports",Guid.NewGuid().ToString("N"),"mod"),"test.import","1.0.0");var settings=new Settings{packageFolders=new List<string>{imported.Folder},versionChoices=new Dictionary<string,string>()};string hash=Data.Hash(Paths.Safe(imported.Folder,imported.Manifest.files[0].source));string archived=PackageVersions.RemoveImport(imported,state,settings);Check(File.Exists(Path.Combine(archived,"mod",Packages.ManifestName))&&Data.Hash(Path.Combine(archived,"mod",imported.Manifest.files[0].source.Replace('/','\\')))==hash,"safe archive retains recoverable original package content");Reject(()=>PackageVersions.RemoveImport(sameA,state,settings),"external and Workshop-like source roots cannot be archived as manager imports");
   ScopeFixtures(root,game,state);
   lines.Add("BENCHMARK cold="+coldMs+"ms warm="+warmMs+"ms; packages=720; cold parses="+cold.ParsedPackages+"; warm parses="+warm.ParsedPackages+"; warm hits="+warm.CacheHits+"; visited="+warm.VisitedDirectories);File.WriteAllLines(Path.Combine(root,"workflow-results.txt"),lines);Console.WriteLine(lines.Last());Console.WriteLine("Workflow evidence: "+root);return 0;
  }
  static void ScopeFixtures(string root,string game,string state){
   string data=Path.Combine(root,"scoped","Data");Directory.CreateDirectory(data);var assets=new List<LegacyAsset>();foreach(string scope in new[]{"12345","54321"}){string rel="Workshop/"+scope+"/Island/Tchinese.dat";string payload=Paths.Safe(data,rel);Directory.CreateDirectory(Path.GetDirectoryName(payload));File.WriteAllText(payload,"translation "+scope);assets.Add(new LegacyAsset{target=rel,sha256=Data.Hash(payload),group="language"});Directory.CreateDirectory(Path.Combine(root,"Library","steamapps","workshop","content","304930",scope,"Island"));}
   Data.Write(Path.Combine(data,"manifest.json"),assets);Data.Write(Path.Combine(data,"version.json"),new LegacyVersion{product="Unturned.AI.Tchinese",version="1.2.0",package_id="test-map",package_label="Same name",manifest_sha256=Data.Hash(Path.Combine(data,"manifest.json"))});var scopes=Packages.LoadAll(Path.GetDirectoryName(data),L.Get("Text227"));Check(scopes.Count==2&&scopes.Select(p=>p.Manifest.id).Distinct().Count()==2,"legacy map package expands into independent scope identities");
   foreach(var package in scopes){var engine=new Engine(game,state,true,false,package.Manifest.scopeId);engine.Install(package,null);}
   var scan=Scanner.Collect(root,state,game,Path.GetDirectoryName(data),new string[0],new string[0],false,delegate{});Check(scan.Installed.Count==2&&scan.Installed.All(p=>p.scopeId!=null),"scan aggregates per-scope installation records");
   var noSource=Scanner.Collect(root,state,game,Path.Combine(root,"empty"),new string[0],new string[0],false,delegate{});Check(noSource.Installed.Count==2,"installed scopes remain discoverable when package source disappears");
   foreach(var package in scopes){var engine=new Engine(game,state,true,false,package.Manifest.scopeId);engine.Uninstall(package.Manifest.id);}
   var interrupted=new Engine(game,state,true,false,"12345");string interruptedFile=Paths.Safe(interrupted.Root,"Island/Tchinese.dat");File.WriteAllText(interruptedFile,"interrupted fixture write");string recordPath=Path.Combine(interrupted.State,"installed.json");File.Delete(recordPath);Data.Write(Path.Combine(interrupted.State,"pending.json"),new Journal{gameRoot=interrupted.Root,ownerGameRoot=game,scopeId="12345",hadRegistry=false,files=new List<Snapshot>{new Snapshot{target="Island/Tchinese.dat",existed=false,saved="transactions/new/0.bak"}}});var pending=Scanner.Collect(root,state,game,Path.Combine(root,"empty"),new string[0],new string[0],false,delegate{});Check(pending.PendingScopes.Contains("12345"),"first scoped install interruption is discoverable even without source or installed record");interrupted.RecoverPending();Check(!interrupted.NeedsRecovery&&!File.Exists(interruptedFile),"orphaned first-install journal safely restores the scoped target");
   string zip=Path.Combine(root,"scoped.zip");ZipFile.CreateFromDirectory(Path.GetDirectoryName(data),zip);var imported=Packages.ImportZip(zip,state);Check(Packages.LoadAll(imported.Folder,L.Get("Text155")).Count==2,"one ZIP package can contain multiple independently installable scopes");var preferences=new Settings{packageFolders=new List<string>{imported.Folder},versionChoices=new Dictionary<string,string>()};string archive=PackageVersions.RemoveImport(imported,state,preferences);Check(Directory.Exists(archive)&&!Directory.Exists(imported.Folder),"multi-scope import is archived as one complete recoverable container");
   string official=Path.Combine(root,"official","Data"),target="Localization/Tchinese/Example.dat";string file=Paths.Safe(official,target);Directory.CreateDirectory(Path.GetDirectoryName(file));File.WriteAllText(file,"official");Data.Write(Path.Combine(official,"manifest.json"),new[]{new LegacyAsset{target=target,sha256=Data.Hash(file),group="language"}});Data.Write(Path.Combine(official,"version.json"),new LegacyVersion{product="Unturned.AI.Tchinese",version="1.2.0",package_id="official",manifest_sha256=Data.Hash(Path.Combine(official,"manifest.json"))});Check(Packages.Load(official,L.Get("Text227")).Manifest.id=="unturned.ai.tchinese","official split package keeps the original core translation identity");
  }
  public static int RealZip(string zip,string baseDir){lines=new List<string>();string root=NewRoot(baseDir,"california-zip-");var first=Packages.ImportZip(zip,root);var scopes=Packages.LoadAll(first.Folder,L.Get("Text155"));Check(scopes.Count==2&&scopes.Sum(p=>p.Manifest.files.Count)==3043,"actual California 2 ZIP imports both scopes without repackaging");Check(scopes.SelectMany(p=>p.Manifest.files.Select(f=>new{p,f})).All(x=>Data.Same(Data.Hash(Paths.Safe(x.p.Folder,x.f.source)),x.f.sha256)),"all 3043 imported payload files match the original manifest hashes");File.WriteAllLines(Path.Combine(root,"zip-results.txt"),lines);Console.WriteLine("ZIP evidence: "+root);return 0;}
  public static int RealPackage(string packageFolder,string originalWorkshop,string baseDir){lines=new List<string>();string root=NewRoot(baseDir,"california-real-"),game=FakeGame(root),state=Path.Combine(root,"state"),workshop=Path.Combine(root,"Library","steamapps","workshop","content","304930");var packages=Packages.LoadAll(packageFolder,L.Get("Text227"));Check(packages.Count==2&&packages.Sum(p=>p.Manifest.files.Count)==3043,"actual California 2 v1.2 exposes two scopes and all 3043 files");Check(packages.Select(p=>p.Manifest.id).Distinct().Count()==2&&packages.All(p=>p.Manifest.id!="unturned.ai.tchinese"),"map and resource IDs cannot collide with the core translation package");
   foreach(var p in packages){string targetRoot=Paths.Safe(workshop,p.Manifest.scopeId);Directory.CreateDirectory(targetRoot);foreach(var f in p.Manifest.files){string primary=f.source_file??f.target.Substring(0,f.target.LastIndexOf('/')+1)+"English.dat";CopyOriginal(originalWorkshop,p.Manifest.scopeId,targetRoot,primary);if(f.source_dependencies!=null)foreach(var d in f.source_dependencies)CopyOriginal(originalWorkshop,p.Manifest.scopeId,targetRoot,d.relative);}
    string seed=Paths.Safe(targetRoot,p.Manifest.files[0].target);Directory.CreateDirectory(Path.GetDirectoryName(seed));File.WriteAllText(seed,"original fixture translation");var engine=new Engine(game,state,true,false,p.Manifest.scopeId);Check(engine.Root.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase),"scope target is confined to isolated fixture: "+p.Manifest.scopeId);engine.Install(p,engine.Collisions(p));Check(engine.ReadRegistry().packages.Single().files.Count==p.Manifest.files.Count,"actual package installs every manifest entry in scope "+p.Manifest.scopeId);Check(p.Manifest.files.All(f=>Data.Same(Data.Hash(Paths.Safe(engine.Root,f.target)),f.sha256)),"all installed translation hashes match the actual package: "+p.Manifest.scopeId);
    string english=p.Manifest.files[0].source_file??p.Manifest.files[0].target.Substring(0,p.Manifest.files[0].target.LastIndexOf('/')+1)+"English.dat",englishPath=Paths.Safe(targetRoot,english),before=Data.Hash(Path.Combine(engine.State,"installed.json"));File.AppendAllText(englishPath,"updated");Reject(()=>engine.Install(p,null),"updated original text stops installation: "+p.Manifest.scopeId);Check(Data.Hash(Path.Combine(engine.State,"installed.json"))==before,"source drift cannot change installation record");CopyOriginal(originalWorkshop,p.Manifest.scopeId,targetRoot,english,true);
    var dependency=p.Manifest.files.FirstOrDefault(f=>f.source_dependencies!=null&&f.source_dependencies.Count>0);if(dependency!=null){var d=dependency.source_dependencies[0];File.AppendAllText(Paths.Safe(targetRoot,d.relative),"changed");Reject(()=>engine.Collisions(p),"supplemental asset drift is rejected");CopyOriginal(originalWorkshop,p.Manifest.scopeId,targetRoot,d.relative,true);}
    engine.FailAfter=0;Reject(()=>engine.Install(p,null),"injected interruption rolls back scoped update");Check(!engine.NeedsRecovery&&p.Manifest.files.All(f=>Data.Same(Data.Hash(Paths.Safe(engine.Root,f.target)),f.sha256)),"rollback preserves installed scoped content");engine.FailAfter=-1;
   }
   var first=packages[0];var firstEngine=new Engine(game,state,true,false,first.Manifest.scopeId);firstEngine.Uninstall(first.Manifest.id);var second=packages[1];var secondEngine=new Engine(game,state,true,false,second.Manifest.scopeId);Check(second.Manifest.files.All(f=>File.Exists(Paths.Safe(secondEngine.Root,f.target))),"restoring map scope preserves independently installed resource scope");secondEngine.Uninstall(second.Manifest.id);Check(packages.All(p=>File.ReadAllText(Paths.Safe(Paths.Safe(workshop,p.Manifest.scopeId),p.Manifest.files[0].target))=="original fixture translation"),"uninstall restores original translations in both scopes");Reject(()=>new Engine(game,state,true,false,"99999999999"),"missing original subscription is never created");Reject(()=>new Engine(game,state,true,false,"../escape"),"unsafe scope ID is rejected");Check(!Directory.Exists(Path.Combine(workshop,"99999999999")),"missing subscription remains absent");
   File.WriteAllLines(Path.Combine(root,"california-results.txt"),lines);Console.WriteLine("California evidence: "+root);return 0;
  }
  static void CopyOriginal(string source,string scope,string target,string relative,bool overwrite=false){string src=Paths.Safe(Paths.Safe(source,scope),relative),dest=Paths.Safe(target,relative);if(!File.Exists(src))throw new Exception("Missing original fixture source: "+src);Directory.CreateDirectory(Path.GetDirectoryName(dest));if(overwrite||!File.Exists(dest))File.Copy(src,dest,overwrite);}
 }
}
